//! Keeps the four places that make a Tauri command usable in sync:
//!
//! 1. `build.rs`  `COMMANDS`     (the application command manifest)
//! 2. `src/lib.rs` `generate_handler![...]` (what is actually registered)
//! 3. `capabilities/default.json` (which `allow-*` permissions the window is granted)
//! 4. `permissions/autogenerated/*.toml` (permission definitions generated by `tauri-build`)
//!
//! Because `build.rs` defines an app manifest, Tauri rejects every command that is not granted
//! by an explicit permission ("not allowed. Command not found"). A handler missing from the other
//! three lists therefore compiles, passes unit tests and mocked E2E tests, and still fails in the
//! real app. These tests fail when that happens.
//!
//! They parse the source files as text on purpose: the lists live in `build.rs`, which cannot be
//! imported, and the check must not depend on Tauri's runtime.

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn read(rel: &str) -> String {
    let path = root().join(rel);
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

/// Removes `//` line comments so commented-out entries are not counted. (No command list in
/// these files contains `//` inside a string.)
fn strip_line_comments(src: &str) -> String {
    src.lines()
        .map(|l| l.split("//").next().unwrap_or(""))
        .collect::<Vec<_>>()
        .join("\n")
}

/// The text between the first `open` after `marker` and its matching `close`.
fn between<'a>(src: &'a str, marker: &str, open: char, close: char) -> &'a str {
    let start = src
        .find(marker)
        .unwrap_or_else(|| panic!("`{marker}` not found"));
    let rest = &src[start..];
    let o = rest
        .find(open)
        .unwrap_or_else(|| panic!("`{open}` not found after `{marker}`"));
    let body = &rest[o + 1..];
    let c = body
        .find(close)
        .unwrap_or_else(|| panic!("`{close}` not found after `{marker}`"));
    &body[..c]
}

fn manifest_commands() -> BTreeSet<String> {
    let src = strip_line_comments(&read("build.rs"));
    // `const COMMANDS: &[&str] = &[ ... ];` -> skip the type's own brackets.
    let after = &src[src.find("const COMMANDS").expect("COMMANDS not found")..];
    let list = between(
        &after[after.find("= &[").expect("COMMANDS list not found")..],
        "&[",
        '[',
        ']',
    );
    list.split(',')
        .map(|s| s.trim().trim_matches('"').to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

fn handler_commands() -> BTreeSet<String> {
    let src = strip_line_comments(&read("src/lib.rs"));
    between(&src, "generate_handler!", '[', ']')
        .split(',')
        .filter_map(|p| p.trim().rsplit("::").next().map(str::to_string))
        .filter(|s| !s.is_empty())
        .collect()
}

fn allow_id(command: &str) -> String {
    format!("allow-{}", command.replace('_', "-"))
}

fn capability_permissions() -> Vec<String> {
    let json: serde_json::Value =
        serde_json::from_str(&read("capabilities/default.json")).expect("capability is JSON");
    json["permissions"]
        .as_array()
        .expect("permissions array")
        .iter()
        .map(|p| {
            p.as_str()
                .expect("string permissions only (no scoped objects expected)")
                .to_string()
        })
        .collect()
}

fn generated_files() -> BTreeSet<String> {
    let dir = root().join("permissions/autogenerated");
    fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok())
        .filter_map(|e| {
            let p = e.path();
            (p.extension()? == "toml").then(|| p.file_stem()?.to_str().map(str::to_string))?
        })
        .collect()
}

fn missing(have: &BTreeSet<String>, want: &BTreeSet<String>) -> Vec<String> {
    want.difference(have).cloned().collect()
}

#[test]
fn the_parsers_find_commands() {
    // Guards the text parsing itself: an empty list would make every other test vacuous.
    assert!(manifest_commands().len() >= 20, "{:?}", manifest_commands());
    assert!(handler_commands().len() >= 20, "{:?}", handler_commands());
    assert!(capability_permissions().len() >= 20);
}

#[test]
fn every_registered_handler_is_in_the_build_manifest_and_vice_versa() {
    let manifest = manifest_commands();
    let handlers = handler_commands();
    assert_eq!(
        missing(&manifest, &handlers),
        Vec::<String>::new(),
        "registered in generate_handler! but missing from build.rs COMMANDS (the real app will \
         reject them with \"not allowed. Command not found\")"
    );
    assert_eq!(
        missing(&handlers, &manifest),
        Vec::<String>::new(),
        "listed in build.rs COMMANDS but not registered in generate_handler!"
    );
}

#[test]
fn every_command_is_granted_by_the_capability() {
    let granted: BTreeSet<String> = capability_permissions().into_iter().collect();
    let wanted: BTreeSet<String> = manifest_commands().iter().map(|c| allow_id(c)).collect();
    assert_eq!(
        missing(&granted, &wanted),
        Vec::<String>::new(),
        "commands without an explicit allow-* permission in capabilities/default.json"
    );
}

#[test]
fn the_capability_grants_nothing_unexpected() {
    let wanted: BTreeSet<String> = manifest_commands().iter().map(|c| allow_id(c)).collect();
    for p in capability_permissions() {
        assert!(!p.contains('*'), "wildcard permission `{p}` is not allowed");
        if p.starts_with("allow-") {
            assert!(
                wanted.contains(&p),
                "`{p}` grants a command that is not in build.rs COMMANDS"
            );
        } else {
            // The only non-app permission this app uses. Adding a plugin or core permission is a
            // security decision: update this list deliberately, in the same change.
            assert_eq!(p, "core:default", "unexpected non-app permission `{p}`");
        }
    }
}

#[test]
fn every_command_has_a_generated_permission_definition() {
    let files = generated_files();
    for command in manifest_commands() {
        assert!(
            files.contains(&command),
            "permissions/autogenerated/{command}.toml is missing. Run a build (cargo build or \
             `npm run tauri dev`) so tauri-build regenerates it, and commit the result."
        );
        let toml = read(&format!("permissions/autogenerated/{command}.toml"));
        assert!(
            toml.contains(&format!("identifier = \"{}\"", allow_id(&command))),
            "{command}.toml does not define `{}`",
            allow_id(&command)
        );
        assert!(
            toml.contains(&format!("commands.allow = [\"{command}\"]")),
            "{command}.toml `allow` permission does not enable `{command}`"
        );
    }
}

#[test]
fn there_are_no_stale_generated_permission_files() {
    let manifest = manifest_commands();
    let stale: Vec<String> = generated_files()
        .into_iter()
        .filter(|f| !manifest.contains(f))
        .collect();
    assert_eq!(
        stale,
        Vec::<String>::new(),
        "permission files for commands no longer in build.rs COMMANDS"
    );
}
